// GENERATED by scripts/bundle-functions.mjs — do not edit by hand.
// Edit supabase/functions/_shared/* and <fn>/source.ts, then re-run the bundler.

// ---------------------------------------------------------------------------
// WorkSense Skill Intelligence Graph engine — the shared, deterministic core.
// Zero LLM calls. Imported by backend functions (Recruitment, Onboarding,
// Recommendation Hub) — never recomputed per page view; results are persisted
// into digital_twins.computed_fits[] and, for skill-match, the durable
// skill_fits table.
//
// Phase 9 (audit rework, engine v3): the score is REQUIREMENT-CENTERED and
// EVIDENCE-CONDITIONED. Every point comes from a requirement being satisfied
// (direct or accepted-adjacent). There is NO global evidence-count component
// and NO seniority component — unrelated evidence or a seniority match can
// never manufacture match points. Evidence quality is an *attenuation factor*
// on each requirement's contribution, and the person's evidence base is
// reported separately (confidence + artifact count) instead of being folded
// into the score.
//
// Two numbers are computed from the same requirement loop:
//   score            = "verified readiness"  — accepted independent evidence
//                      only (reviewer_confirmed / assessment_supported).
//   profile_match    = "provisional profile match" — all live claims, each
//                      attenuated by the evidence factor of its review state.
//
// Mandatory requirements are normalized in their own section and gated: if a
// mandatory requirement has no accepted evidence, mandatory_gate is unmet and
// the readiness is flagged (an unmet mandatory can never raise the number it
// is gated on). Preferred requirements are normalized separately.
// ---------------------------------------------------------------------------

export type VerificationRigor = "low" | "medium" | "high";

/** Bump when the scoring semantics change — stale cached fits are recomputed. */
export const ENGINE_VERSION = "3";

/** Evidence factor by assertion state: how much of a claim's contribution
 *  counts toward the *provisional* profile match. Verified readiness only
 *  accepts the two reviewed states (factor 1). */
export const EVIDENCE_FACTOR: Record<string, number> = {
  reviewer_confirmed: 1,
  assessment_supported: 0.85,
  extracted: 0.5,
  claimed: 0.4,
  // invalidated states never score (expired/disputed/superseded) — factor 0
  expired: 0,
  disputed: 0,
  superseded: 0,
};

/** States treated as accepted, independent evidence. */
export const ACCEPTED_STATES = new Set(["reviewer_confirmed", "assessment_supported"]);

export interface SkillClaim {
  name: string;
  proficiency: number;
  evidence_source: string;
  verification_rigor: VerificationRigor;
}

export type EdgeType = "PREREQUISITE_OF" | "ADJACENT_TO" | "TRANSFERABLE_TO";

export interface GraphEdge {
  target_skill: string;
  type: EdgeType;
  weight: number; // 0.0 - 1.0
}

export interface GraphSkill {
  skill: string;
  category: string;
  outgoing_edges: GraphEdge[];
}

export interface RequiredSkill {
  skill: string;
  target_proficiency: number;
  /** Default true. Preferred criteria are normalized in their own section. */
  mandatory?: boolean;
  /** Optional explicit weight; otherwise normalized equally within the group. */
  criterion_weight?: number;
  /** Explicitly obsolete — removed from the resolved future target. */
  obsolete?: boolean;
}

/**
 * Phase 9: six honest support classifications.
 *  - verified_direct       direct evidence, accepted, at/above target
 *  - provisional_direct    direct evidence, NOT accepted, at/above target
 *  - below_target          direct evidence exists but below the target bar
 *  - adjacent_support      no direct skill; a real ADJACENT_TO edge from a claim
 *  - transferable_foundation  weakest signal: no proficiency, development only
 *  - missing               no direct, adjacent, or transferable path
 */
export type Classification =
  | "verified_direct"
  | "provisional_direct"
  | "below_target"
  | "adjacent_support"
  | "transferable_foundation"
  | "missing";

export type Relationship = "direct" | "adjacent" | "transferable" | "none";

export interface FitItem {
  skill: string;
  classification: Classification;
  relationship: Relationship;
  mandatory: boolean;
  required_proficiency: number;
  /** Observed level (direct claim, or the supporting claim for adjacent). */
  candidate_proficiency: number | null;
  /** The level credit actually applied toward the requirement (0 when none). */
  effective_proficiency: number;
  /** Target minus effective credit, floored at 0. */
  gap: number;
  /** Direct acceptance state of the best supporting assertion (null = none). */
  evidence_state: string | null;
  /** Source artifact key or evidence source behind the best supporting claim. */
  evidence_source: string | null;
  /** Age in days of the newest supporting assertion (null = unknown). */
  freshness_days: number | null;
  /** Evidence factor (0-1) attenuating the provisional credit. */
  evidence_factor: number;
  /** Verified credit (0-1): accepted direct ratio or accepted-adjacent value. */
  verified_contribution: number | null;
  /** Provisional credit (0-1): full credit attenuated by evidence factor. */
  contribution: number | null;
  /** Counts toward verified readiness. */
  verified: boolean;
  /** Counts toward the provisional profile match. */
  provisional: boolean;
  /** Deterministic next action for this requirement. */
  next_action: string;
  edge: { from_skill: string; type: EdgeType; weight: number } | null;
  reason: string;
  /** Honest limitation of this classification (never equivalence). */
  limitation?: string | null;
}

/** One row of the requirement-by-requirement matrix. */
export type RequirementScore = FitItem;

export interface FitRecord {
  target_type: "requisition";
  target_id: string;
  target_title: string;
  scenario: "current" | "future";
  /** Verified readiness (0-1, 3dp) — today's accepted evidence vs the
   *  requirement set this scenario evaluates. */
  score: number;
  /** Provisional profile match (0-1, 3dp) — all live claims, attenuated. */
  profile_match: number;
  /** Weighted mean evidence factor over contributing requirements (0-1). */
  evidence_confidence: number;
  /** Mandatory gate: met only when every mandatory requirement has a
   *  non-zero verified contribution. */
  mandatory_gate: {
    met: boolean;
    unmet_skills: string[];
    count: number;
    note: string;
  };
  /** Seniority is informational context, never part of the score. */
  contextual_alignment: {
    candidate_level: number;
    role_level: number;
    note: string;
  };
  scoring: {
    requirements: RequirementScore[];
    mandatory: { count: number; met: number; unmet: number; unmet_skills: string[]; gated: boolean; readiness: number | null };
    preferred: { count: number; readiness: number | null } | null;
    verified: { readiness: number };
    provisional: { readiness: number };
    confidence: number;
    group_weights: { mandatory: number; preferred: number };
    evidence_artifacts: { count: number; threshold: number };
    resolved_from: "current" | "resolved-future";
    /** For the future scenario: how the evaluated set was derived. */
    derivation?: { kept: string[]; added: string[]; raised: string[]; obsolete: string[] };
  };
  classification: Record<Classification, FitItem[]>;
  versions?: {
    engine: string;
    evidence: string;
    requisition: string;
    graph?: string;
    context?: string;
    plan?: string;
  };
  assumptions?: {
    horizon: string;
    note: string;
  };
  computed_at: string;
}

/** Group weights between the mandatory and preferred sections. Within each
 *  section, requirements are normalized by count (or their criterion_weight). */
export const GROUP_WEIGHTS = {
  mandatory: 0.7,
  preferred: 0.3,
} as const;

/** Informational only (artifact count / evidence confidence) — this is NOT a
 *  score component anymore. Kept for display of the evidence base. */
export const DEFAULT_EVIDENCE_THRESHOLD = 5;

const norm = (s: string) => s.trim().toLowerCase();

export function findEdge(
  skillGraph: GraphSkill[],
  from: string,
  to: string,
  type: EdgeType
): GraphEdge | null {
  const node = skillGraph.find((n) => norm(n.skill) === norm(from));
  const edge = node?.outgoing_edges.find(
    (e) => norm(e.target_skill) === norm(to) && e.type === type
  );
  return edge ?? null;
}

const round3 = (n: number) => Math.round(n * 1000) / 1000;
const mean = (xs: number[]) => (xs.length === 0 ? 0 : xs.reduce((a, b) => a + b, 0) / xs.length);

/** Deterministic FNV-1a hex (uniquely named to avoid bundle collisions). */
export function graphFnv1aHex(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/**
 * Version hash over the requisition's skill content. Phase 9: covers the
 * normalized current set, the resolved future set, mandatory/preferred status,
 * target proficiency, criterion weight, seniority target and obsolete list —
 * any change invalidates cached fits.
 */
export function requisitionContentHash(params: {
  current: RequiredSkill[];
  future: RequiredSkill[];
  resolvedFuture: RequiredSkill[];
  seniorityLevel: number;
  obsolete?: RequiredSkill[];
}): string {
  const line = (s: RequiredSkill, tag: string) =>
    `${tag}:${norm(s.skill)}|t${s.target_proficiency}|m${s.mandatory === false ? 0 : 1}|w${s.criterion_weight ?? ""}`;
  const payload = [
    ...(params.current ?? []).map((s) => line(s, "cur")).sort(),
    ...(params.future ?? []).map((s) => line(s, "fut")).sort(),
    ...(params.resolvedFuture ?? []).map((s) => line(s, "res")).sort(),
    ...(params.obsolete ?? []).map((s) => line(s, "obs")).sort(),
    `level:${params.seniorityLevel}`,
  ].join(";");
  return graphFnv1aHex(payload);
}

/** Version hash over the person's resolved skill claims. */
export function claimHash(claims: SkillClaim[]): string {
  const payload = (claims ?? [])
    .map((c) => `${norm(c.name)}|${c.proficiency}|${c.evidence_source}|${c.verification_rigor}`)
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/**
 * Phase 9: the full evidence fingerprint. Covers assertion ids, review states,
 * effective proficiency, evidence ids, artifact keys and captured_at/expiry —
 * so accepting, correcting, rejecting, expiring or replacing any assertion or
 * artifact invalidates every cached fit that depended on it.
 */
export function evidenceDetailHash(lineage: {
  assertions: { id: string; skill_id?: string; claimed_proficiency: number; review_state: string; evidence_ids?: string[]; created_at?: string }[];
  evidence: { id: string; source_type?: string | null; source_id?: string | null; captured_at?: string | null; review_state?: string }[];
}): string {
  const artifactKey = (e: { source_type?: string | null; source_id?: string | null; id: string }) =>
    e.source_id ? `artifact:${e.source_type ?? "unknown"}|${e.source_id}` : `item:${e.id}`;
  const parts = [
    ...(lineage.assertions ?? []).map((a) =>
      `a:${a.id}|s${a.skill_id ?? ""}|p${a.claimed_proficiency}|r${a.review_state}|e[${(a.evidence_ids ?? []).sort().join(",")}]|c${a.created_at ?? ""}`
    ),
    ...(lineage.evidence ?? []).map((e) =>
      `ev:${e.id}|k${artifactKey(e)}|c${e.captured_at ?? ""}|r${e.review_state ?? ""}`
    ),
  ].sort();
  return graphFnv1aHex(parts.join(";"));
}

/** Version hash over the whole graph (nodes + typed edges). */
export function graphContentHash(
  graph: { skill: string; outgoing_edges: { target_skill: string; type: string; weight: number }[] }[]
): string {
  const payload = (graph ?? [])
    .flatMap((n) => [
      `node:${n.skill}`,
      ...(n.outgoing_edges ?? []).map((e) => `${n.skill}|${e.type}|${e.target_skill}|${e.weight}`),
    ])
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/** Person-level context that affects the *display* (contextual alignment,
 *  evidence base) — not the score itself. Kept in the fingerprint so the
 *  cached result is recomputed when this context changes. */
export function personContextHash(candidateLevel: number, evidenceArtifactCount: number | undefined, claimCount: number): string {
  const artifacts = evidenceArtifactCount !== undefined ? evidenceArtifactCount : claimCount;
  return graphFnv1aHex(`level:${candidateLevel}|artifacts:${artifacts}`);
}

export function fitIsStale(
  fit: FitRecord | null,
  current: { engine: string; evidence: string; requisition: string; graph?: string; context?: string; plan?: string }
): boolean {
  if (!fit) return true;
  const v = fit.versions;
  if (!v) return true; // pre-version fits are always stale
  if (v.engine !== current.engine || v.evidence !== current.evidence || v.requisition !== current.requisition) return true;
  if (current.graph !== undefined && (v.graph ?? undefined) !== current.graph) return true;
  if (current.context !== undefined && (v.context ?? undefined) !== current.context) return true;
  if (current.plan !== undefined && (v.plan ?? "none") !== current.plan) return true;
  return false;
}

const HORIZON_LABEL: Record<string, string> = {
  current: "Current requirements — as recorded on the requisition today. Verified readiness answers: how much of today's requirement is already backed by accepted evidence?",
  future: "Resolved 12–24 month target — today's still-relevant requirements plus future additions, with raised targets applied. Verified readiness answers: how much of the future target is already backed by accepted evidence TODAY (no assumed learning)?",
};

/** Map a claim's evidence_source/rigor to {accepted, factor, state}. */
function evidenceMeta(source: string, rigor: VerificationRigor): { accepted: boolean; factor: number; state: string } {
  const s = (source ?? "").toLowerCase();
  if (s === "evidence_review") return { accepted: true, factor: EVIDENCE_FACTOR.reviewer_confirmed, state: "reviewer_confirmed" };
  if (s === "assessment") return { accepted: true, factor: EVIDENCE_FACTOR.assessment_supported, state: "assessment_supported" };
  if (s === "resume_extraction") return { accepted: false, factor: EVIDENCE_FACTOR.extracted, state: "extracted" };
  if (s === "self_report") return { accepted: false, factor: EVIDENCE_FACTOR.claimed, state: "claimed" };
  if (rigor === "high") return { accepted: true, factor: EVIDENCE_FACTOR.reviewer_confirmed, state: "reviewer_confirmed" };
  if (rigor === "medium") return { accepted: true, factor: EVIDENCE_FACTOR.assessment_supported, state: "assessment_supported" };
  return { accepted: false, factor: EVIDENCE_FACTOR.claimed, state: "claimed" };
}

/** Dedup claims per skill (case-insensitive), keeping the strongest evidence
 *  first, then the highest proficiency. Defends against legacy duplicates. */
function dedupeClaims(claims: SkillClaim[]): SkillClaim[] {
  const best = new Map<string, SkillClaim>();
  for (const c of claims ?? []) {
    const key = norm(c.name);
    if (!key) continue;
    const cur = best.get(key);
    const rank = (x: SkillClaim) => {
      const m = evidenceMeta(x.evidence_source, x.verification_rigor);
      return m.accepted ? (m.factor === 1 ? 3 : 2) : 1;
    };
    if (!cur || rank(c) > rank(cur) || (rank(c) === rank(cur) && c.proficiency > cur.proficiency)) {
      best.set(key, c);
    }
  }
  return [...best.values()];
}

const NEXT_ACTION: Record<Classification, string> = {
  verified_direct: "None — requirement met with accepted evidence.",
  provisional_direct: "Verify evidence — accepted evidence would confirm this match.",
  below_target: "Close the gap to the target level, then re-verify.",
  adjacent_support: "Capability in the required skill itself is not yet evidenced — confirm via an assessment.",
  transferable_foundation: "No proficiency yet — a development candidate, not capability.",
  missing: "No evidence or path — needs an assessment or structured learning.",
};

/** Age of the newest supporting assertion in days (null when unknown). */
function freshnessDays(capturedAt: string | null | undefined, computedAt: string | undefined): number | null {
  if (!capturedAt) return null;
  const now = computedAt ? new Date(computedAt).getTime() : Date.now();
  const then = new Date(capturedAt).getTime();
  if (Number.isNaN(then)) return null;
  return Math.max(0, Math.round((now - then) / 86400000));
}

function evaluateRequirement(
  req: RequiredSkill,
  claims: SkillClaim[],
  graph: GraphSkill[],
  evidenceDetail: Record<string, { captured_at?: string | null; artifact_key?: string | null }>,
  computedAt: string | undefined
): FitItem {
  const target = req.target_proficiency;
  const mandatory = req.mandatory !== false;
  const detail = evidenceDetail?.[norm(req.skill)];

  // ---- Direct claim for the required skill ----
  const own = claims.find((s) => norm(s.name) === norm(req.skill));
  if (own) {
    const meta = evidenceMeta(own.evidence_source, own.verification_rigor);
    const ratio = Math.min(1, own.proficiency / target);
    const verifiedContribution = meta.accepted ? ratio : 0;
    const provisionalContribution = ratio * meta.factor;
    const effective = Math.min(own.proficiency, target);
    const classification: Classification =
      own.proficiency >= target
        ? meta.accepted
          ? "verified_direct"
          : "provisional_direct"
        : "below_target";
    return {
      skill: req.skill,
      classification,
      relationship: "direct",
      mandatory,
      required_proficiency: target,
      candidate_proficiency: own.proficiency,
      effective_proficiency: effective,
      gap: Math.max(0, target - effective),
      evidence_state: meta.state,
      evidence_source: detail?.artifact_key ?? meta.state,
      freshness_days: freshnessDays(detail?.captured_at, computedAt),
      evidence_factor: meta.factor,
      verified_contribution: round3(verifiedContribution),
      contribution: round3(provisionalContribution),
      verified: verifiedContribution > 0,
      provisional: true,
      next_action: NEXT_ACTION[classification],
      edge: null,
      reason: `Holds ${req.skill} at ${own.proficiency}/${target} required — evidence state: ${meta.state}.`,
      limitation: null,
    };
  }

  // ---- Adjacent: no direct skill, but a real ADJACENT_TO edge from a claim ----
  let bestAdj: { from: string; edge: GraphEdge; value: number; claim: SkillClaim } | null = null;
  for (const claim of claims) {
    const edge = findEdge(graph, claim.name, req.skill, "ADJACENT_TO");
    if (edge) {
      const value = Math.min(1, (claim.proficiency / 5) * edge.weight);
      if (!bestAdj || value > bestAdj.value) bestAdj = { from: claim.name, edge, value, claim };
    }
  }
  if (bestAdj) {
    const meta = evidenceMeta(bestAdj.claim.evidence_source, bestAdj.claim.verification_rigor);
    const verifiedContribution = meta.accepted ? bestAdj.value : 0;
    const provisionalContribution = bestAdj.value * meta.factor;
    const effective = Math.min(bestAdj.value * target, target);
    return {
      skill: req.skill,
      classification: "adjacent_support",
      relationship: "adjacent",
      mandatory,
      required_proficiency: target,
      candidate_proficiency: bestAdj.claim.proficiency,
      effective_proficiency: round3(effective),
      gap: round3(Math.max(0, target - effective)),
      evidence_state: meta.state,
      evidence_source: detail?.artifact_key ?? meta.state,
      freshness_days: freshnessDays(detail?.captured_at, computedAt),
      evidence_factor: meta.factor,
      verified_contribution: round3(verifiedContribution),
      contribution: round3(provisionalContribution),
      verified: verifiedContribution > 0,
      provisional: true,
      next_action: NEXT_ACTION.adjacent_support,
      edge: { from_skill: bestAdj.from, type: "ADJACENT_TO", weight: bestAdj.edge.weight },
      reason: `No direct ${req.skill}; backed by ${bestAdj.from} → ${req.skill} (ADJACENT_TO, ${bestAdj.edge.weight.toFixed(2)}).`,
      limitation: "Adjacent support is NOT direct equivalence: this person has no evidence for the required skill itself. Confirm real capability before relying on it.",
    };
  }

  // ---- Transferable: no direct/adjacent edge, but a TRANSFERABLE_TO edge or
  //      strong same-category relationship. Never contributes points. ----
  let transfer: { from: string; edge: GraphEdge | null; via: string } | null = null;
  for (const claim of claims) {
    const edge = findEdge(graph, claim.name, req.skill, "TRANSFERABLE_TO");
    if (edge) {
      transfer = { from: claim.name, edge, via: "edge" };
      break;
    }
    if (!transfer) {
      const ownNode = graph.find((n) => norm(n.skill) === norm(claim.name));
      const reqNode = graph.find((n) => norm(n.skill) === norm(req.skill));
      if (ownNode && reqNode && ownNode.category && ownNode.category === reqNode.category) {
        transfer = { from: claim.name, edge: null, via: `same category (${ownNode.category})` };
      }
    }
  }
  if (transfer) {
    return {
      skill: req.skill,
      classification: "transferable_foundation",
      relationship: "transferable",
      mandatory,
      required_proficiency: target,
      candidate_proficiency: null,
      effective_proficiency: 0,
      gap: target,
      evidence_state: null,
      evidence_source: null,
      freshness_days: null,
      evidence_factor: 0,
      verified_contribution: 0,
      contribution: 0,
      verified: false,
      provisional: false,
      next_action: NEXT_ACTION.transferable_foundation,
      edge: transfer.edge
        ? { from_skill: transfer.from, type: "TRANSFERABLE_TO", weight: transfer.edge.weight }
        : null,
      reason: transfer.edge
        ? `No direct or adjacent path; ${transfer.from} → ${req.skill} is transferable.`
        : `No direct or adjacent path; ${transfer.from} shares the ${transfer.via}.`,
      limitation: "Transferable support is the weakest signal: it establishes no proficiency in the required skill and contributes no points to the score. Treat it as a development candidate, not capability.",
    };
  }

  // ---- Missing ----
  return {
    skill: req.skill,
    classification: "missing",
    relationship: "none",
    mandatory,
    required_proficiency: target,
    candidate_proficiency: null,
    effective_proficiency: 0,
    gap: target,
    evidence_state: null,
    evidence_source: null,
    freshness_days: null,
    evidence_factor: 0,
    verified_contribution: 0,
    contribution: 0,
    verified: false,
    provisional: false,
    next_action: NEXT_ACTION.missing,
    edge: null,
    reason: `No direct, adjacent, or transferable path found for ${req.skill}.`,
    limitation: null,
  };
}

/** Build the canonical requirement list for a scenario. For "future" the
 *  caller passes the RESOLVED future target (see resolveFutureRequirements).
 *  Defaults: skills carry mandatory=true unless flagged. */
export function normalizeRequirements(skills: RequiredSkill[]): RequiredSkill[] {
  const seen = new Map<string, RequiredSkill>();
  for (const s of skills ?? []) {
    const key = norm(s.skill);
    if (!key) continue;
    seen.set(key, {
      skill: s.skill,
      target_proficiency: s.target_proficiency,
      mandatory: s.mandatory !== false,
      criterion_weight: s.criterion_weight,
      obsolete: s.obsolete,
    });
  }
  return [...seen.values()];
}

/**
 * Phase 9: the resolved 12–24 month target.
 *   = current requirements (minus explicitly-obsolete) + future additions,
 *     with future targets applied (raised targets raise, additions are future
 *     capability signals → preferred).
 * A current skill missing from the future list is KEPT unless explicitly
 * marked obsolete — removals only happen on explicit intent.
 */
export function resolveFutureRequirements(
  current: RequiredSkill[],
  future: RequiredSkill[],
  obsolete: RequiredSkill[] = []
): { resolved: RequiredSkill[]; kept: string[]; added: string[]; raised: string[]; obsolete: string[] } {
  const curList = normalizeRequirements(current);
  const futList = normalizeRequirements(future);
  const obsKeys = new Set(normalizeRequirements(obsolete).map((o) => norm(o.skill)));
  const curMap = new Map(curList.map((r) => [norm(r.skill), r]));
  const futMap = new Map(futList.map((r) => [norm(r.skill), r]));

  const resolved: RequiredSkill[] = [];
  const kept: string[] = [];
  const added: string[] = [];
  const raised: string[] = [];

  for (const cur of curList) {
    const key = norm(cur.skill);
    if (obsKeys.has(key)) continue;
    const fut = futMap.get(key);
    if (fut) {
      resolved.push({ ...cur, target_proficiency: fut.target_proficiency });
      if (fut.target_proficiency > cur.target_proficiency) raised.push(cur.skill);
      else kept.push(cur.skill);
    } else {
      resolved.push(cur);
      kept.push(cur.skill);
    }
  }
  for (const fut of futList) {
    const key = norm(fut.skill);
    if (curMap.has(key)) continue;
    resolved.push({ ...fut, mandatory: false }); // future capability signal
    added.push(fut.skill);
  }
  return { resolved, kept, added, raised, obsolete: [...obsKeys] };
}

export function computeFit(params: {
  candidateSkills: SkillClaim[];
  candidateLevel: number;
  requiredSkills: RequiredSkill[];
  roleLevel: number;
  skillGraph: GraphSkill[];
  threshold?: number;
  target: { type: "requisition"; id: string; title: string };
  scenario: "current" | "future";
  computedAt?: string;
  /** Distinct artifact count behind the claims (display only now). */
  evidenceArtifactCount?: number;
  /** Per-requirement evidence detail (freshness / artifact source). */
  evidenceDetail?: Record<string, { captured_at?: string | null; artifact_key?: string | null }>;
  /** Pre-computed evidence fingerprint (superset of claimHash). */
  evidenceVersion?: string;
  /** Requisition content hash (stale detection). */
  requisitionVersion?: string;
  /** Optional development-plan version; "none" when no plan is approved. */
  planVersion?: string;
  /** Derivation metadata for the future scenario. */
  derivation?: { kept: string[]; added: string[]; raised: string[]; obsolete: string[] };
}): FitRecord {
  const threshold = params.threshold ?? DEFAULT_EVIDENCE_THRESHOLD;
  const claims = dedupeClaims(params.candidateSkills);
  const required = normalizeRequirements(params.requiredSkills ?? []);
  const computedAt = params.computedAt ?? new Date().toISOString();

  const items: FitItem[] = required.map((r) =>
    evaluateRequirement(r, claims, params.skillGraph, params.evidenceDetail ?? {}, computedAt)
  );

  const mandatoryItems = items.filter((i) => i.mandatory);
  const preferredItems = items.filter((i) => !i.mandatory);

  const groupVerified = (list: FitItem[]) =>
    list.length === 0 ? null : mean(list.map((i) => i.verified_contribution ?? 0));
  const groupProvisional = (list: FitItem[]) =>
    list.length === 0 ? null : mean(list.map((i) => i.contribution ?? 0));

  const mVerified = groupVerified(mandatoryItems);
  const pVerified = groupVerified(preferredItems);
  const mProvisional = groupProvisional(mandatoryItems);
  const pProvisional = groupProvisional(preferredItems);

  const { mandatory: wM, preferred: wP } = GROUP_WEIGHTS;
  const verifiedReadiness =
    mVerified !== null && pVerified !== null
      ? wM * mVerified + wP * pVerified
      : mVerified ?? pVerified ?? 0;
  const provisionalReadiness =
    mProvisional !== null && pProvisional !== null
      ? wM * mProvisional + wP * pProvisional
      : mProvisional ?? pProvisional ?? 0;

  // Evidence confidence: weighted mean factor over requirements with any
  // contribution — a measure of the evidence BASE, not a score component.
  const contributing = items.filter((i) => (i.contribution ?? 0) > 0);
  const confidence = contributing.length === 0 ? 0 : mean(contributing.map((i) => i.evidence_factor));

  // Mandatory gate: every mandatory requirement needs accepted evidence.
  const unmetMandatory = mandatoryItems.filter((i) => (i.verified_contribution ?? 0) <= 0);
  const gate = {
    met: unmetMandatory.length === 0,
    unmet_skills: unmetMandatory.map((i) => i.skill),
    count: mandatoryItems.length,
    note:
      unmetMandatory.length === 0
        ? mandatoryItems.length === 0
          ? "No mandatory criteria are defined for this demand."
          : "Every mandatory requirement has accepted evidence (direct or accepted-adjacent)."
        : `Unmet: ${unmetMandatory.map((i) => i.skill).join(", ")}. Without accepted evidence these cannot raise verified readiness.`,
  };

  const classification: Record<Classification, FitItem[]> = {
    verified_direct: items.filter((i) => i.classification === "verified_direct"),
    provisional_direct: items.filter((i) => i.classification === "provisional_direct"),
    below_target: items.filter((i) => i.classification === "below_target"),
    adjacent_support: items.filter((i) => i.classification === "adjacent_support"),
    transferable_foundation: items.filter((i) => i.classification === "transferable_foundation"),
    missing: items.filter((i) => i.classification === "missing"),
  };

  const evidenceVersion = params.evidenceVersion ?? claimHash(claims);
  const artifactCount =
    params.evidenceArtifactCount !== undefined
      ? params.evidenceArtifactCount
      : claims.filter((s) => s.verification_rigor === "high" || s.verification_rigor === "medium").length;

  return {
    target_type: params.target.type,
    target_id: params.target.id,
    target_title: params.target.title,
    scenario: params.scenario,
    score: round3(verifiedReadiness),
    profile_match: round3(provisionalReadiness),
    evidence_confidence: round3(confidence),
    mandatory_gate: gate,
    contextual_alignment: {
      candidate_level: params.candidateLevel,
      role_level: params.roleLevel,
      note: `Seniority (${params.candidateLevel} vs ${params.roleLevel} role level) is shown as context only — it never contributes to the match score.`,
    },
    scoring: {
      requirements: items,
      mandatory: {
        count: mandatoryItems.length,
        met: mandatoryItems.length - unmetMandatory.length,
        unmet: unmetMandatory.length,
        unmet_skills: unmetMandatory.map((i) => i.skill),
        gated: unmetMandatory.length > 0,
        readiness: mVerified === null ? null : round3(mVerified),
      },
      preferred: preferredItems.length === 0 ? null : { count: preferredItems.length, readiness: pVerified === null ? null : round3(pVerified) },
      verified: { readiness: round3(verifiedReadiness) },
      provisional: { readiness: round3(provisionalReadiness) },
      confidence: round3(confidence),
      group_weights: { mandatory: wM, preferred: wP },
      evidence_artifacts: { count: artifactCount, threshold },
      resolved_from: params.scenario === "future" ? "resolved-future" : "current",
      ...(params.derivation ? { derivation: params.derivation } : {}),
    },
    classification,
    versions: {
      engine: ENGINE_VERSION,
      evidence: evidenceVersion,
      requisition: params.requisitionVersion ?? "unknown",
      graph: graphContentHash(params.skillGraph),
      context: personContextHash(params.candidateLevel, params.evidenceArtifactCount, claims.length),
      plan: params.planVersion ?? "none",
    },
    assumptions: {
      horizon: params.scenario === "future" ? "Resolved 12–24 month target" : "Current",
      note: HORIZON_LABEL[params.scenario],
    },
    computed_at: computedAt,
  };
}

/** Cache key for computed_fits[] entries. */
export function fitKey(record: { target_type: string; target_id: string; scenario: string }) {
  return `${record.target_type}|${record.target_id}|${record.scenario}`;
}

/**
 * Skill-match authorization — a pure, role-scoped decision shared by the
 * backend function (server enforcement) and unit tests. Deliberately does not
 * decide ownership on the client.
 *
 * Scopes:
 *   org        — administrator (any twin) / HR partner (workforce twins only)
 *   candidates — recruiter (candidate twins only)
 *   team       — manager (direct/recursive reports, self handled separately)
 *   self       — manager self / employee self
 *   denied     — everything else (IT, candidate callers, cross-org, out of scope)
 */
export type SkillMatchScope = "org" | "candidates" | "team" | "self" | "denied";

export interface AuthorizeSkillMatchArgs {
  callerRole: string;
  callerOrgId: string;
  callerTwinId: string;
  targetOrgId: string;
  targetTwinId: string;
  targetRole: string;
  /** Pre-resolved subtree check (manager only); a failed lookup must be false. */
  targetIsInCallerTeam: boolean;
}

export function authorizeSkillMatch(args: AuthorizeSkillMatchArgs): SkillMatchScope {
  const { callerRole, callerOrgId, callerTwinId, targetOrgId, targetTwinId, targetRole, targetIsInCallerTeam } = args;
  if (!callerOrgId || targetOrgId !== callerOrgId) return "denied";

  if (callerRole === "hr_executive") return "org";
  if (callerRole === "hr_partner") return targetRole === "candidate" ? "denied" : "org";
  if (callerRole === "recruiter") return targetRole === "candidate" ? "candidates" : "denied";
  if (callerRole === "manager") {
    if (targetTwinId === callerTwinId) return "self";
    return targetIsInCallerTeam ? "team" : "denied";
  }
  if (callerRole === "employee") {
    return targetTwinId === callerTwinId ? "self" : "denied";
  }
  return "denied";
}


// ---------------------------------------------------------------------------
// WorkSense evidence model — normalized source of truth for skills.
// skill_assertions (claimed / extracted / assessment_supported /
// reviewer_confirmed / …) each reference evidence_items (quote, source,
// captured_at). digital_twins.verified_skills stays a denormalized cache of
// *confirmed* skills only (reviewer_confirmed / assessment_supported); legacy
// records without assertions fall back to verified_skills. Resume extractions
// write 'extracted' assertions (rigor "low") — they never inflate the
// confirmed list or the fit evidence score.
// ---------------------------------------------------------------------------



export type ReviewState =
  | "claimed"
  | "extracted"
  | "assessment_supported"
  | "reviewer_confirmed"
  | "expired"
  | "disputed"
  | "superseded";

export const REVIEW_STATES: ReviewState[] = [
  "claimed",
  "extracted",
  "assessment_supported",
  "reviewer_confirmed",
  "expired",
  "disputed",
  "superseded",
];

export interface AssertionRow {
  id: string;
  org_id: string;
  twin_id: string;
  skill_id: string;
  claimed_proficiency: number;
  proficiency_tier: string | null;
  review_state: ReviewState;
  evidence_ids: string[];
  created_at: string;
  /** Joined from skill_graph (not a column). */
  skill_name?: string | null;
}

export interface EvidenceRow {
  id: string;
  org_id: string;
  twin_id: string | null;
  source_type: string;
  source_id: string | null;
  source_version: string | null;
  captured_at: string;
  quote: string | null;
  span: string | null;
  review_state: ReviewState;
  reviewed_by: string | null;
  reviewed_at: string | null;
  metadata: Record<string, unknown>;
}

/** States that still represent a live claim (scoring includes them, at a
 *  rigor derived from how they were confirmed). Invalidated records
 *  (expired/disputed/superseded) stay visible for lineage but never score. */
const SCORABLE_STATES = new Set<ReviewState>([
  "claimed",
  "extracted",
  "assessment_supported",
  "reviewer_confirmed",
]);

const RIGOR_BY_STATE: Record<ReviewState, SkillClaim["verification_rigor"]> = {
  reviewer_confirmed: "high",
  assessment_supported: "medium",
  extracted: "low",
  claimed: "low",
  expired: "low",
  disputed: "low",
  superseded: "low",
};

/** Highest-confidence state wins when several assertions target one skill. */
const STATE_RANK: Record<ReviewState, number> = {
  reviewer_confirmed: 5,
  assessment_supported: 4,
  extracted: 3,
  claimed: 2,
  expired: 1,
  disputed: 1,
  superseded: 1,
};

export function evidenceSourceForState(state: ReviewState): string {
  switch (state) {
    case "reviewer_confirmed":
      return "evidence_review";
    case "assessment_supported":
      return "assessment";
    case "extracted":
      return "resume_extraction";
    case "claimed":
      return "self_report";
    default:
      return "evidence_record";
  }
}

/** Map skill_assertions (enriched with skill_name) to engine SkillClaims.
 *  Dedup per skill keeping the strongest review state; invalidated states are
 *  excluded from scoring. */
export function buildSkillClaims(assertions: AssertionRow[]): SkillClaim[] {
  const best = new Map<string, AssertionRow>();
  for (const a of assertions) {
    if (!SCORABLE_STATES.has(a.review_state)) continue;
    const name = (a.skill_name ?? "").trim();
    if (!name) continue;
    const key = name.toLowerCase();
    const cur = best.get(key);
    if (
      !cur ||
      STATE_RANK[a.review_state] > STATE_RANK[cur.review_state] ||
      (STATE_RANK[a.review_state] === STATE_RANK[cur.review_state] &&
        a.claimed_proficiency > cur.claimed_proficiency)
    ) {
      best.set(key, a);
    }
  }
  return [...best.values()].map((a) => ({
    name: (a.skill_name ?? "").trim(),
    proficiency: a.claimed_proficiency,
    evidence_source: evidenceSourceForState(a.review_state),
    verification_rigor: RIGOR_BY_STATE[a.review_state] ?? "low",
  }));
}

/** Load a twin's skill_assertions, joined with canonical skill names. */
export async function loadAssertions(supabase, twinId: string): Promise<AssertionRow[]> {
  const { data, error } = await supabase
    .from("skill_assertions")
    .select(
      "id, org_id, twin_id, skill_id, claimed_proficiency, proficiency_tier, review_state, evidence_ids, created_at"
    )
    .eq("twin_id", twinId);
  if (error) throw error;
  const rows = (data ?? []) as AssertionRow[];
  if (rows.length === 0) return rows;

  const skillIds = [...new Set(rows.map((r) => r.skill_id))];
  const { data: skills, error: skillErr } = await supabase
    .from("skill_graph")
    .select("id, skill")
    .in("id", skillIds);
  if (skillErr) throw skillErr;
  const nameById = new Map<string, string>((skills ?? []).map((s) => [String(s.id), String(s.skill)]));
  return rows.map((r) => ({ ...r, skill_name: nameById.get(r.skill_id) ?? null }));
}

/** Load evidence_items by id, preserving input order. */
export async function loadEvidence(supabase, evidenceIds: string[]): Promise<EvidenceRow[]> {
  const ids = [...new Set(evidenceIds ?? [])];
  if (ids.length === 0) return [];
  const { data, error } = await supabase.from("evidence_items").select("*").in("id", ids);
  if (error) throw error;
  const byId = new Map((data ?? []).map((e) => [e.id, e as EvidenceRow]));
  return ids.map((id) => byId.get(id)).filter((e): e is EvidenceRow => Boolean(e));
}

/** Full lineage for a twin: assertions (enriched) + their evidence. */
export async function resolveLineage(
  supabase,
  twinId: string
): Promise<{ assertions: AssertionRow[]; evidence: EvidenceRow[] }> {
  const assertions = await loadAssertions(supabase, twinId);
  const evidenceIds = [...new Set(assertions.flatMap((a) => a.evidence_ids ?? []))];
  const evidence = await loadEvidence(supabase, evidenceIds);
  return { assertions, evidence };
}

/** Phase 8: distinct supporting artifacts behind a twin's scored assertions.
 *  An artifact is keyed by its source (e.g. one resume document or one work
 *  sample). Multiple assertions from the SAME artifact deduplicate to ONE
 *  artifact — a skill assertion is never counted as a separate independent
 *  artifact, and one artifact cannot inflate the evidence score N times. */
export function evidenceArtifactKey(e: { source_type?: string | null; source_id?: string | null; id: string }): string {
  if (e.source_id) return `artifact:${e.source_type ?? "unknown"}|${e.source_id}`;
  return `item:${e.id}`;
}

export async function resolveEvidenceArtifacts(
  supabase,
  twinId: string
): Promise<{ artifact_keys: string[]; count: number }> {
  const lineage = await resolveLineage(supabase, twinId);
  const keys = [...new Set(lineage.evidence.map(evidenceArtifactKey))];
  return { artifact_keys: keys, count: keys.length };
}

/** Claims for scoring: assertions when present (canonical), otherwise the
 *  legacy verified_skills jsonb (golden seed / pre-migration records). */
export async function resolveSkillClaims(
  supabase,
  twin: { id: string; verified_skills?: unknown }
): Promise<SkillClaim[]> {
  const assertions = await loadAssertions(supabase, twin.id);
  if (assertions.length > 0) return buildSkillClaims(assertions);
  return (twin.verified_skills ?? []) as SkillClaim[];
}

/** Resolve a skill name to its skill_graph id for an org, creating the concept
 *  row on first sight (the graph is a growing canonical concept store). */
export async function resolveSkillId(supabase, orgId: string, skillName: string): Promise<string> {
  const name = String(skillName ?? "").trim();
  if (!name) throw new Error("resolveSkillId: empty skill name");
  const { data } = await supabase
    .from("skill_graph")
    .select("id")
    .eq("org_id", orgId)
    .eq("skill", name)
    .maybeSingle();
  if (data) return data.id;
  const { data: created, error } = await supabase
    .from("skill_graph")
    .insert({
      org_id: orgId,
      skill: name,
      category: "Uncategorized",
      outgoing_edges: [],
      aliases: [],
    })
    .select("id")
    .single();
  if (error) throw error;
  return created.id;
}


// ---------------------------------------------------------------------------
// WorkSense resume ingestion helpers (Phase 4). Deterministic, shared by the
// resume-import / resume-review / resume-download backend functions.
// Security rules implemented here: content sniffing (never trust the extension),
// safe filenames, size caps, checksum dedup, quote-to-source validation and
// alias normalization against the skill taxonomy. No raw SQL; no client writes.
// ---------------------------------------------------------------------------

export const MAX_FILE_BYTES = 4 * 1024 * 1024; // 4 MiB demo limit
export const ALLOWED_EXTENSIONS = ["pdf", "docx"];
export const LOW_TEXT_CHARS = 160; // below this the document is treated as scanned/low-text

export type SniffedType = "pdf" | "docx" | "unknown";

/** Detect the real document type from magic bytes, not the file extension. */
export function sniffDocType(bytes: Uint8Array): SniffedType {
  if (bytes.length >= 5) {
    const head = String.fromCharCode(...bytes.slice(0, 5));
    if (head === "%PDF-") return "pdf";
  }
  if (bytes.length >= 4) {
    const pk = [bytes[0], bytes[1], bytes[2], bytes[3]];
    if (pk[0] === 0x50 && pk[1] === 0x4b && (pk[2] === 0x03 || pk[2] === 0x05 || pk[2] === 0x07)) return "docx"; // PK zip
  }
  return "unknown";
}

/** Strip paths/control chars; keep a safe basename with its extension. */
export function sanitizeFileName(raw: string): string {
  const base = String(raw ?? "").split(/[\\/]/).pop() ?? "";
  const cleaned = [...base]
    .filter((ch) => {
      const c = ch.charCodeAt(0);
      return c >= 0x20 && c !== 0x7f;
    })
    .join("")
    .trim()
    .slice(0, 120);
  return cleaned;
}

export function fileSizeMessage(bytes: number): string {
  if (bytes > MAX_FILE_BYTES) return `File is ${(bytes / 1024 / 1024).toFixed(1)} MiB — the limit is 4 MiB.`;
  return "";
}

export async function sha256Hex(bytes: Uint8Array): Promise<string> {
  const buf = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer;
  const digest = await crypto.subtle.digest("SHA-256", buf);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export interface GraphSkillRow {
  skill: string;
  aliases?: string[];
}

/** Normalize a claimed skill name against the taxonomy (exact then aliases).
 *  Postgres → PostgreSQL when the alias list says so; never creates duplicates. */
export function normalizeSkillName(graphRows: GraphSkillRow[], claim: string): string {
  const name = String(claim ?? "").trim();
  if (!name) return name;
  const lower = name.toLowerCase();
  const exact = graphRows.find((g) => g.skill.toLowerCase() === lower);
  if (exact) return exact.skill;
  const alias = graphRows.find((g) =>
    (g.aliases ?? []).some((a) => a.trim().toLowerCase() === lower)
  );
  return alias ? alias.skill : name;
}

const normWs = (s: string) => String(s ?? "").replace(/\s+/g, " ").trim();

/** A quote is valid only if it appears verbatim (whitespace-normalized) in the
 *  source text — the basis for rejecting fabricated quotes at save time. */
export function quoteMatchesSource(quote: string, sourceText: string): boolean {
  const q = normWs(quote);
  if (q.length === 0) return false;
  return normWs(sourceText).includes(q);
}

/** Overlapping date ranges must not double-count experience. Unknown dates stay
 *  unknown (excluded from the computed total). `present` resolves to the clock. */
export function computeTotalYears(
  roles: { title: string; start: string; end: string }[],
  clockIso: string
): { total_years: number; deduped: number; overlap_warnings: string[] } {
  const clock = new Date(clockIso).getTime();
  const parse = (v: string): number | null => {
    const m = /^(\d{4})-(\d{2})/.exec(v ?? "");
    return m ? new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, 1)).getTime() : null;
  };
  const intervals: { start: number; end: number; label: string }[] = [];
  const overlap_warnings: string[] = [];
  for (const r of roles) {
    const start = parse(r.start);
    let end = parse(r.end);
    if (r.end === "present" || /present|now|current/i.test(r.end ?? "")) end = clock;
    if (start === null || end === null) {
      if (start === null) overlap_warnings.push(`${r.title}: start date unknown — excluded from the computed total.`);
      continue;
    }
    intervals.push({ start, end, label: r.title });
  }
  intervals.sort((a, b) => a.start - b.start);
  const merged: { start: number; end: number; labels: string[] }[] = [];
  for (const iv of intervals) {
    const last = merged[merged.length - 1];
    if (last && iv.start <= last.end) {
      if (iv.end > last.end) last.end = iv.end;
      last.labels.push(iv.label);
      if (last.labels.length > 1 && !overlap_warnings.some((w) => w.includes("overlapping"))) {
        overlap_warnings.push(`Overlapping dates detected (${last.labels.join(", ")} + ${iv.label}) — experience not double-counted.`);
      }
    } else {
      merged.push({ start: iv.start, end: iv.end, labels: [iv.label] });
    }
  }
  const totalMs = merged.reduce((n, m) => n + Math.max(0, m.end - m.start), 0);
  return {
    total_years: Math.round((totalMs / (365.25 * 86400000)) * 10) / 10,
    deduped: merged.length,
    overlap_warnings,
  };
}


// ---------------------------------------------------------------------------
// WorkSense fit store (Batch 6 — cross-module handoffs).
// One canonical fit source: the `skill_fits` table (atomic upsert per
// twin + target + scenario), which candidate-compare and the Fit card read.
// `computed_fits` on digital_twins is only a legacy mirror. resume-review and
// assessment-review recompute fits when evidence/claims change and MUST write
// the canonical row — otherwise the hiring comparison shows a stale score.
// ---------------------------------------------------------------------------

export interface FitLike {
  target_type?: string;
  target_id?: string;
  scenario?: string;
  [k: string]: unknown;
}

/** Replace any stored fit for the same target + scenario; never lose others. */
export function mergeLegacyFits(fits: FitLike[], incoming: FitLike): FitLike[] {
  const others = (fits ?? []).filter(
    (f) => !(f.target_id === incoming.target_id && f.scenario === incoming.scenario)
  );
  return [...others, incoming];
}

/** Append one labeled audit event (never clobber history). */
export function appendAuditEvent(events: unknown[], event: unknown): unknown[] {
  return [...(events ?? []), event];
}

/**
 * Persist a recomputed fit to the canonical skill_fits row and mirror it into
 * the twin's legacy computed_fits array. Idempotent per (twin, target,
 * scenario): a concurrent recompute for a different target is never lost.
 */
export async function upsertSkillFit(
  supabase: {
    from: (table: string) => {
      upsert: (rows: unknown, opts: { onConflict: string }) => Promise<{ error: { message: string } | null }>;
      select: (cols: string) => {
        eq: (col: string, value: string) => Promise<{ data: { computed_fits?: unknown[]; audit_events?: unknown[] } | null }>;
      };
      update: (patch: Record<string, unknown>) => {
        eq: (col: string, value: string) => Promise<unknown>;
      };
    };
  },
  params: {
    orgId: string;
    twinId: string;
    targetId: string;
    scenario: "current" | "future";
    fit: unknown;
    computedAt: string;
    actor?: string;
    action?: string;
    note?: string;
  }
) {
  const { error } = await supabase
    .from("skill_fits")
    .upsert(
      {
        org_id: params.orgId,
        twin_id: params.twinId,
        target_type: "requisition",
        target_id: params.targetId,
        scenario: params.scenario,
        fit: params.fit,
        computed_at: params.computedAt,
      },
      { onConflict: "twin_id,target_type,target_id,scenario" }
    );
  if (error) throw error;

  // Best-effort legacy mirror (source of truth stays skill_fits).
  const { data: twin } = await supabase
    .from("digital_twins")
    .select("computed_fits, audit_events")
    .eq("id", params.twinId);
  if (twin) {
    const fitLike = params.fit as FitLike;
    const fits = mergeLegacyFits((twin.computed_fits ?? []) as FitLike[], fitLike);
    const patch: Record<string, unknown> = { computed_fits: fits };
    if (params.note) {
      patch.audit_events = appendAuditEvent(twin.audit_events ?? [], {
        actor: params.actor ?? "system",
        action: params.action ?? "fit_refreshed",
        note: params.note,
        timestamp: params.computedAt,
      });
    }
    await supabase.from("digital_twins").update(patch).eq("id", params.twinId);
  }
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";





const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const TIER_PROFICIENCY: Record<string, number> = { FOUNDATIONAL: 1, INTERMEDIATE: 3, ADVANCED: 4, EXPERT: 5 };
const sourceTypeFor = () => "resume_document";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHENTICATED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, email, org_id, name")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller || !["hr_executive", "hr_partner", "recruiter"].includes(caller.role)) {
    return json({ error: "FORBIDDEN", message: "Recruitment access required." }, 403);
  }

  let body: { document_id?: string; twin_id?: string; req_id?: string; version_id?: string; review?: unknown } = {};
  try {
    body = await req.json();
  } catch {
    /* empty */
  }
  const documentId = (body.document_id ?? "").trim();
  const twinId = (body.twin_id ?? "").trim();
  if (!documentId || !twinId || !body.review) {
    return json({ error: "VALIDATION_ERROR", message: "document_id, twin_id and the reviewed extraction are required." }, 400);
  }

  const { data: doc } = await supabase
    .from("resume_documents")
    .select("id, org_id, twin_id, extracted_text, checksum, status")
    .eq("id", documentId)
    .maybeSingle();
  if (!doc) return json({ error: "NOT_FOUND", message: "Resume document not found." }, 404);
  if (doc.org_id !== caller.org_id || doc.twin_id !== twinId) return json({ error: "FORBIDDEN" }, 403);
  if (doc.status === "failed" || doc.status === "low_text") {
    return json({ error: "CONFLICT", message: "This document has no extractable text to review." }, 409);
  }
  const sourceText = doc.extracted_text ?? "";

  const review = body.review as {
    full_name?: string;
    contact?: Record<string, string>;
    roles?: { title: string; company: string; start?: string; end?: string; years_claimed?: number; quote: string }[];
    education?: { institution: string; degree: string; year: string; quote: string }[];
    certifications?: { name: string; issuer: string; year: string; quote: string }[];
    projects?: { name: string; role: string; tech_stack: string[]; impact_metric: string; quote: string }[];
    skill_claims?: { skill: string; years?: number; proficiency_tier: string; quote: string; association: string }[];
    ambiguities?: string[];
    conflicts?: string[];
  };

  // ---- Evidence validation: every quote must exist in the stored source text.
  const quoteViolations: string[] = [];
  const checkQuote = (quote: string, label: string) => {
    if (!quoteMatchesSource(quote, sourceText)) {
      quoteViolations.push(`${label}: quote not found in source — "${quote.slice(0, 100)}${quote.length > 100 ? "…" : ""}"`);
    }
  };
  for (const [i, r] of (review.roles ?? []).entries()) checkQuote(r.quote, `role[${i}]`);
  for (const [i, e] of (review.education ?? []).entries()) checkQuote(e.quote, `education[${i}]`);
  for (const [i, c] of (review.certifications ?? []).entries()) checkQuote(c.quote, `certification[${i}]`);
  for (const [i, p] of (review.projects ?? []).entries()) checkQuote(p.quote, `project[${i}]`);
  for (const [i, s] of (review.skill_claims ?? []).entries()) checkQuote(s.quote, `skill[${s.skill ?? i}]`);
  if (quoteViolations.length > 0) {
    return json({ error: "VALIDATION_ERROR", message: "Fabricated quotes cannot be saved.", details: quoteViolations }, 422);
  }

  // ---- Alias normalization (defense in depth — never create duplicates).
  const { data: graphRows } = await supabase.from("skill_graph").select("skill, aliases").eq("org_id", caller.org_id);
  const graph = (graphRows ?? []) as { skill: string; aliases?: string[] }[];
  const claims = (review.skill_claims ?? []).map((c) => ({
    ...c,
    skill: normalizeSkillName(graph, c.skill),
    proficiency_tier: (c.proficiency_tier ?? "FOUNDATIONAL").toUpperCase(),
  }));

  // Conflict resolution: keep reviewer_confirmed/assessment_supported untouched;
  // replace this twin's prior resume-extracted ('extracted') assertions only.
  const { data: prior } = await supabase
    .from("skill_assertions")
    .select("id, evidence_ids")
    .eq("twin_id", twinId)
    .eq("review_state", "extracted");
  const priorEv = (prior ?? []).flatMap((r) => r.evidence_ids ?? []);
  if (priorEv.length > 0) await supabase.from("evidence_items").delete().in("id", priorEv);
  if ((prior ?? []).length > 0) await supabase.from("skill_assertions").delete().in("id", (prior ?? []).map((r) => r.id));

  // Latest version number (reprocessing creates a new version, history preserved).
  const { data: verMax } = await supabase
    .from("resume_versions")
    .select("version")
    .eq("document_id", documentId)
    .order("version", { ascending: false })
    .limit(1)
    .maybeSingle();
  const version = (verMax?.version ?? 0) + 1;
  const now = new Date().toISOString();

  // Evidence per skill claim (+ project evidence for lineage).
  const evidenceRows: { org_id: string; twin_id: string; source_type: string; source_id: string; captured_at: string; quote: string; review_state: string; metadata: Record<string, unknown> }[] = [];
  const seenSkills = new Set<string>();
  const dedupedClaims: typeof claims = [];
  for (const c of claims) {
    const key = c.skill.toLowerCase();
    if (seenSkills.has(key)) continue; // repeated claim for one skill -> one assertion
    seenSkills.add(key);
    dedupedClaims.push(c);
    evidenceRows.push({
      org_id: caller.org_id, twin_id: twinId, source_type: sourceTypeFor(),
      source_id: `doc:${documentId}:v${version}`, captured_at: now,
      quote: c.quote, review_state: "extracted",
      metadata: { skill: c.skill, years: c.years ?? 0, association: c.association ?? "explicit", version },
    });
  }
  for (const [i, p] of (review.projects ?? []).entries()) {
    evidenceRows.push({
      org_id: caller.org_id, twin_id: twinId, source_type: sourceTypeFor(),
      source_id: `doc:${documentId}:v${version}`, captured_at: now,
      quote: p.quote, review_state: "extracted",
      metadata: { project: p.name, project_index: i, version },
    });
  }

  const { data: evRows, error: evErr } = await supabase.from("evidence_items").insert(evidenceRows).select("id");
  if (evErr) throw evErr;
  const evIds = (evRows ?? []).map((r) => r.id);

  // Assertions: claims remain claims ('extracted', low rigor) — uploading and
  // extraction never upgrade skills to verified.
  const assertionRows = [];
  for (let i = 0; i < dedupedClaims.length; i++) {
    assertionRows.push({
      org_id: caller.org_id, twin_id: twinId,
      skill_id: await resolveSkillId(supabase, caller.org_id, dedupedClaims[i].skill),
      claimed_proficiency: TIER_PROFICIENCY[dedupedClaims[i].proficiency_tier] ?? 2,
      proficiency_tier: dedupedClaims[i].proficiency_tier,
      review_state: "extracted",
      evidence_ids: [evIds[i]],
    });
  }
  const { error: assertErr } = await supabase.from("skill_assertions").insert(assertionRows);
  if (assertErr) throw assertErr;

  // Mark version reviewed + document reviewed.
  const { error: verErr2 } = await supabase.from("resume_versions").insert({
    org_id: caller.org_id, document_id: documentId, twin_id: twinId, version,
    source_hash: doc.checksum, payload: { ...review, skill_claims: dedupedClaims },
    review_state: "reviewed", reviewed_by: caller.id, reviewed_at: now,
  });
  if (verErr2) throw verErr2;
  const { error: docErr } = await supabase.from("resume_documents").update({ status: "reviewed", updated_at: now }).eq("id", documentId);
  if (docErr) throw docErr;

  const audit = [{ actor: caller.email ?? uid, action: "resume_reviewed", note: `Reviewed resume version ${version} (${dedupedClaims.length} claims, ${evidenceRows.length} evidence). Claims recorded as extracted — not verified.`, timestamp: now }];
  const { data: twinRow } = await supabase.from("digital_twins").select("audit_events, computed_fits, verified_skills, seniority_level").eq("id", twinId).maybeSingle();
  if (twinRow) {
    await supabase.from("digital_twins").update({ audit_events: [...(twinRow.audit_events ?? []), ...audit] }).eq("id", twinId);
  }

  // Refreshed fit (engine, assertions now include extracted claims at low rigor).
  let fit = null;
  if (body.req_id) {
    const reqId = body.req_id.trim();
    const { data: reqRow } = await supabase.from("job_requisitions").select("id, title, required_skills, seniority_level").eq("id", reqId).maybeSingle();
    if (reqRow) {
      const { data: assertions } = await supabase
        .from("skill_assertions")
        .select("skill_id, claimed_proficiency, proficiency_tier, review_state, evidence_ids, twin_id")
        .eq("twin_id", twinId);
      const { data: skills } = await supabase.from("skill_graph").select("id, skill").eq("org_id", caller.org_id);
      const nameById = new Map((skills ?? []).map((s) => [s.id, s.skill]));
      const claims2 = (assertions ?? [])
        .filter((a) => ["reviewer_confirmed", "assessment_supported", "extracted", "claimed"].includes(a.review_state))
        .map((a) => ({
          name: nameById.get(a.skill_id) ?? "",
          proficiency: a.claimed_proficiency,
          evidence_source: a.review_state === "extracted" ? "resume_extraction" : a.review_state === "reviewer_confirmed" ? "evidence_review" : "assessment",
          verification_rigor: a.review_state === "reviewer_confirmed" ? ("high" as const) : a.review_state === "assessment_supported" ? ("medium" as const) : ("low" as const),
        }))
        .filter((c) => c.name);
      const { data: graphAll } = await supabase.from("skill_graph").select("skill, category, outgoing_edges").eq("org_id", caller.org_id);
      fit = computeFit({
        candidateSkills: claims2,
        candidateLevel: twinRow?.seniority_level ?? 3,
        requiredSkills: reqRow.required_skills ?? [],
        roleLevel: reqRow.seniority_level ?? 3,
        skillGraph: graphAll ?? [],
        target: { type: "requisition", id: reqRow.id, title: reqRow.title },
        scenario: "current",
        computedAt: now,
      });
      // Batch 6: persist to the CANONICAL skill_fits row (comparison reads it)
      // plus the legacy mirror, so a resume review invalidates the stale fit.
      await upsertSkillFit(supabase, {
        orgId: caller.org_id,
        twinId,
        targetId: reqRow.id,
        scenario: "current",
        fit,
        computedAt: now,
        actor: caller.email ?? uid,
        action: "resume_reviewed",
        note: `Resume v${version} reviewed (${dedupedClaims.length} claims — extracted, not verified). Fit current ${fit.score.toFixed(3)}.`,
      });
    }
  }

  return json({
    ok: true,
    document_id: documentId,
    version,
    claims_saved: dedupedClaims.length,
    evidence_saved: evidenceRows.length,
    conflicts_resolved: review.conflicts ?? [],
    fit,
    provenance: {
      artifact_ref: `doc:${documentId}:v${version}`,
      file_name: doc.file_name,
      checksum_short: doc.checksum.slice(0, 12),
      source_type: "resume_document",
    },
  });
});
